library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity Audio_capture_controller is

    generic
    (
        DATA_WIDTH   : integer := 16;
        SAMPLE_COUNT : integer := 512
    );

    port
    (
        clk  : in std_logic;
        rstn : in std_logic;

        ----------------------------------------------------
        -- Capture command from PS / Register Controller
        ----------------------------------------------------

        send_packet : in std_logic;

        ----------------------------------------------------
        -- Generated by FFT/PSD block
        ----------------------------------------------------

        DataValid : in std_logic;

        ----------------------------------------------------
        -- High while BRAM is being read
        ----------------------------------------------------

        MemBusy : out std_logic;

        ----------------------------------------------------
        -- BRAM Port B
        ----------------------------------------------------

        bram_rd_addr : out std_logic_vector(8 downto 0);
        bram_rd_data : in  std_logic_vector(DATA_WIDTH-1 downto 0);

        ----------------------------------------------------
        -- AXI-Stream output
        ----------------------------------------------------

        m_axis_tdata  : out std_logic_vector(DATA_WIDTH-1 downto 0);
        m_axis_tvalid : out std_logic;
        m_axis_tready : in std_logic;
        m_axis_tlast  : out std_logic;

        ----------------------------------------------------
        -- Status
        ----------------------------------------------------

        capture_start_status : out std_logic;
        capture_done         : out std_logic
    );

end entity;


architecture rtl of Audio_capture_controller is

    --------------------------------------------------------
    -- FSM
    --
    -- READ_WAIT:
    --     BRAM address has been applied.
    --
    -- READ_CAPTURE:
    --     Wait/capture BRAM output after 1-cycle latency.
    --
    -- READ_DATA:
    --     Present captured data to AXI-Stream.
    --------------------------------------------------------

    type state_type is
    (
        IDLE,
        READ_WAIT,
        READ_CAPTURE,
        READ_DATA
    );

    signal state : state_type;

    --------------------------------------------------------
    -- BRAM read address
    --------------------------------------------------------

    signal rd_addr : unsigned(8 downto 0);

    --------------------------------------------------------
    -- Number of samples already transferred
    --------------------------------------------------------

    signal sample_counter : unsigned(11 downto 0);

    --------------------------------------------------------
    -- AXI-Stream data register
    --------------------------------------------------------

    signal data_reg : std_logic_vector(DATA_WIDTH-1 downto 0);

    --------------------------------------------------------
    -- AXI-Stream valid
    --------------------------------------------------------

    signal output_valid : std_logic;

    --------------------------------------------------------
    -- Synchronized capture command
    --------------------------------------------------------

    signal send_packet_Sync : std_logic;

    signal send_packet_prev  : std_logic;
    signal capture_start_Flag : std_logic;


    --------------------------------------------------------
    -- Synchronizer
    --------------------------------------------------------

    COMPONENT send_packet_sync_core is
        Port (
            clk        : in  std_logic;
            reset      : in  std_logic;
            lock_async : in  std_logic;
            lock_sync  : out std_logic
        );
    end COMPONENT;


begin

    --------------------------------------------------------
    -- Synchronize send_packet
    --------------------------------------------------------

    Inst_send_packet_Lock_Sync : send_packet_sync_core
        port map (
            clk        => clk,
            reset      => rstn,
            lock_async => send_packet,
            lock_sync  => send_packet_Sync
        );


    --------------------------------------------------------
    -- Capture start detection
    --------------------------------------------------------

    process (clk, rstn)
    begin

        if rstn = '0' then

            send_packet_prev   <= '0';
            capture_start_Flag <= '0';
            capture_start_status <= '0';

        elsif rising_edge(clk) then

            send_packet_prev <= send_packet_Sync;

            ------------------------------------------------
            -- Rising edge of synchronized send_packet
            ------------------------------------------------

            if (send_packet_prev = '0' and
                send_packet_Sync = '1') then

                capture_start_Flag   <= '1';
                capture_start_status <= '1';

            end if;


            ------------------------------------------------
            -- Capture has started reading data
            ------------------------------------------------

            if state = READ_DATA then

                capture_start_Flag   <= '0';
                capture_start_status <= '0';

            end if;

        end if;

    end process;


    --------------------------------------------------------
    -- BRAM address
    --------------------------------------------------------

    bram_rd_addr <= std_logic_vector(rd_addr);


    --------------------------------------------------------
    -- AXI-Stream data
    --------------------------------------------------------

    m_axis_tdata <= data_reg;


    --------------------------------------------------------
    -- AXI-Stream valid
    --------------------------------------------------------

    m_axis_tvalid <= output_valid;


    --------------------------------------------------------
    -- AXI-Stream TLAST
    --
    -- TLAST is asserted together with the last sample.
    --------------------------------------------------------

    m_axis_tlast <= '1'
        when
        (
            output_valid = '1' and
            sample_counter = SAMPLE_COUNT-1
        )
        else '0';


    --------------------------------------------------------
    -- Memory Busy
    --
    -- BRAM is considered busy during the complete read
    -- operation, including the BRAM read-latency cycle.
    --------------------------------------------------------

    MemBusy <= '1'
        when
        (
            state = READ_WAIT or
            state = READ_CAPTURE or
            state = READ_DATA
        )
        else '0';


    --------------------------------------------------------
    -- Main FSM
    --------------------------------------------------------

    process(clk)

    begin

        if rising_edge(clk) then

            ------------------------------------------------
            -- Reset
            ------------------------------------------------

            if rstn = '0' then

                state <= IDLE;

                rd_addr <= (others => '0');

                sample_counter <= (others => '0');

                data_reg <= (others => '0');

                output_valid <= '0';

                capture_done <= '0';


            else

                ------------------------------------------------
                -- Default
                ------------------------------------------------

                capture_done <= '0';


                case state is


                    ------------------------------------------------
                    -- IDLE
                    ------------------------------------------------

                    when IDLE =>

                        output_valid <= '0';

                        rd_addr <= (others => '0');

                        sample_counter <= (others => '0');


                        ------------------------------------------------
                        -- Start capture when:
                        --
                        -- 1. capture command detected
                        -- 2. 512 samples are ready
                        ------------------------------------------------

                        if
                        (
--                            send_packet_Sync = '1' and
                            capture_start_Flag = '1' and
                            DataValid = '1'
                        )
                        then

                            ------------------------------------------------
                            -- Start reading from address 0
                            ------------------------------------------------

                            rd_addr <= (others => '0');

                            sample_counter <= (others => '0');

                            state <= READ_WAIT;

                        end if;


                    ------------------------------------------------
                    -- READ_WAIT
                    --
                    -- BRAM Port B has one clock cycle read latency.
                    --
                    -- Address is already present on bram_rd_addr.
                    -- Do NOT capture bram_rd_data yet.
                    ------------------------------------------------

                    when READ_WAIT =>

                        state <= READ_CAPTURE;


                    ------------------------------------------------
                    -- READ_CAPTURE
                    --
                    -- One clock has elapsed since the address was
                    -- presented to the synchronous BRAM.
                    --
                    -- bram_rd_data is now valid for rd_addr.
                    ------------------------------------------------

                    when READ_CAPTURE =>

                        data_reg <= bram_rd_data;

                        output_valid <= '1';

                        state <= READ_DATA;


                    ------------------------------------------------
                    -- READ_DATA
                    --
                    -- Wait for AXI-Stream handshake.
                    ------------------------------------------------

                    when READ_DATA =>

                        if output_valid = '1' then

                            if m_axis_tready = '1' then


                                ------------------------------------------------
                                -- Last sample
                                ------------------------------------------------

                                if sample_counter = SAMPLE_COUNT-1 then

                                    output_valid <= '0';

                                    capture_done <= '1';

                                    rd_addr <= (others => '0');

                                    sample_counter <= (others => '0');

                                    state <= IDLE;


                                ------------------------------------------------
                                -- Next sample
                                ------------------------------------------------

                                else

                                    ------------------------------------------------
                                    -- Increment sample counter
                                    ------------------------------------------------

                                    sample_counter <= sample_counter + 1;

                                    ------------------------------------------------
                                    -- Increment BRAM address
                                    ------------------------------------------------

                                    rd_addr <= rd_addr + 1;

                                    ------------------------------------------------
                                    -- Remove valid for this cycle
                                    -- while next BRAM data is being fetched.
                                    ------------------------------------------------

                                    output_valid <= '0';

                                    state <= READ_WAIT;

                                end if;

                            end if;

                        end if;


                    ------------------------------------------------
                    -- Safety
                    ------------------------------------------------

                    when others =>

                        state <= IDLE;

                        output_valid <= '0';

                        rd_addr <= (others => '0');

                        sample_counter <= (others => '0');

                end case;

            end if;

        end if;

    end process;

end architecture;